const obj = JSON.parse(readFileSync(OBJ, "utf8"));
const byIata = new Map(obj.airports.filter((a) => a.iata).map((a) => [a.iata, a]));
const report = [];
let yes = 0, no = 0, unk = 0;
for (const [iata, d] of Object.entries(DATA)) {
  const a = byIata.get(iata);
  if (!a) { report.push(`  ?  ${iata} — inconnu du catalogue`); continue; }
  const pr = a.pet_relief ?? (a.pet_relief = {});
  // Le schéma prévoit « unknown » : on l'affirme plutôt que de laisser le champ absent.
  pr.available = d.available === null ? "unknown" : d.available;
  if (d.post === null) delete pr.post_security; else pr.post_security = d.post;
  pr.basis = d.available === null ? "unverified" : "airport_official";
  pr.locations = d.locs;
  if (d.assistance) pr.assistance_only = true; else delete pr.assistance_only;
  pr.note = d.note;
  pr.source = { url: d.url, source_type: "official_website", verified_date: TODAY,
    review_due: DUE, confidence: d.conf, reviewer: "research", history: pr.source?.history ?? [] };
  const verdict = d.available === "yes" ? "zone confirmée" : d.available === "no" ? "AUCUNE zone" : "non publié";
  if (d.available === "yes") yes++; else if (d.available === "no") no++; else unk++;
  report.push(`  ${d.available === "yes" ? "✓" : d.available === "no" ? "✗" : "?"}  ${iata}  ${verdict.padEnd(16)} ${d.locs.length} emplacement(s)   confiance ${d.conf}/5`);
}
console.log(report.sort().join("\n"));
console.log("\n" + "─".repeat(60));
console.log(`${yes} avec zone · ${no} sans zone (sourcé) · ${unk} non publié`);
if (dry) { console.log("\n(--dry : rien n'a été écrit)"); process.exit(0); }
writeFileSync(OBJ, JSON.stringify(obj, null, 2) + "\n");
console.log("objects.json mis à jour.");
